/* Paused character sheet and read-only cultivation progress. */
const CharacterUI=(()=>{
  let before='playing',tab='stats',giftDraft=null,giftError='',menuPlayer=null,menuScroll=0;
  const n=v=>Number(v.toFixed(2)).toLocaleString('zh-CN');
  function init(){document.getElementById('characterBtn').onclick=toggle;}
  function toggle(){
    if(G.state==='character-preview'){close();return;}
    if(G.state==='start'){openFromMenu(Journey.run.heroId);return;}
    if(G.state==='character'){close();return;}
    if(!['playing','paused','win'].includes(G.state))return;
    before=G.state;clearInput();G.state='character';tab='stats';giftDraft=null;giftError='';draw();
  }
  function close(){if(G.state==='character-preview'){const id=menuPlayer.heroId;menuPlayer=null;G.state='start';Journey.menu();const ov=document.getElementById('overlay');ov.scrollTop=menuScroll;ov.querySelector('[data-hero="'+id+'"]').focus?.({preventScroll:true});return;}if(G.state!=='character')return;clearInput();document.getElementById('overlay').classList.add('hidden');G.state=before==='paused'?'playing':before;if(before==='paused')togglePause();if(before==='win'){G.state='win';Journey.showEnd(true);}RunSave.save('关闭人物');}
  function openFromMenu(heroId){
    if(G.state!=='start'||!HeroIdentity.valid(heroId))return false;
    const saved=RunSave.snapshot()?.run.player,legacy=JourneyProgress.replay(RunSave.summary()?.stage??Journey.selected(),Journey.run.difficulty,Journey.difficulties);
    menuPlayer=JSON.parse(JSON.stringify(saved||legacy||newPlayer()));menuPlayer.heroId=heroId;if(!saved&&!legacy)menuPlayer.hp=menuPlayer.maxHp=Journey.difficulty().hp;
    const p=menuPlayer,c=p.cultivation,caps=Cultivation.caps(p),ov=document.getElementById('overlay');menuScroll=ov.scrollTop;
    clearInput();G.state='character-preview';ov.classList.remove('hidden','journey-screen','title-screen');
    const row=(name,value,limit,suffix='')=>`<div class="attribute-row"><span>${name}</span><b>${n(value)}${suffix}</b><small>上限 ${n(limit)}${suffix}</small></div>`;
    const spells=Object.entries(p.spells).map(([id,level])=>`<div class="inventory-item"><b>${SPELLS[id].name} · Lv.${level}</b><small>本境上限 Lv.${Math.max(level,SpellGrowth.cap(c.realm))}</small></div>`).join('');
    const equips=p.equips.map(id=>{const e=EQUIPS.find(e=>e.id===id);return `<div class="inventory-item"><b>${ItemCatalog.icon(id,e.name)}${e.name}</b><small>${e.desc}</small></div>`;}).join('')||'<p>暂无法宝</p>';
    const materials=[['essence','灵蕴精华'],...Cultivation.cores.map((name,i)=>['core'+(i+1),name])].filter(([id])=>c.materials[id]>0).map(([id,name])=>`<div class="material-item">${ItemCatalog.icon(id,name)}<span>${name}</span><b>${c.materials[id]}</b></div>`).join('')||'<p>暂无天材地宝</p>';
    ov.innerHTML=`<div class="panel character-panel" role="dialog" aria-modal="true" aria-label="人物状态"><header class="character-header"><div><span class="overline">无籍剑仙 · ${HeroIdentity.get(heroId).name}</span><h2>${Cultivation.label(c)}</h2><p>战斗等级 Lv.${p.level} · 经验 ${n(p.xp)} / ${n(p.xpNext)} · 剑意 ${n(p.energy)}%</p></div><button id="closeCharacterBtn" aria-label="关闭人物面板">×</button></header><p class="sheet-note">${saved||legacy?'当前存档成长 · 两位剑仙共享成长，外观随所选人物展示':'初始人物状态'} · 查看后可返回选择同行剑仙</p><div class="character-constellation"><div class="hero-survival">${row('生命',p.hp,p.maxHp)}${row('生命上限',p.maxHp,caps.maxHp)}${row('护盾',p.shield,p.shieldMax)}${row('护盾上限',p.shieldMax,caps.shieldMax)}${row('减伤',p.armor*100,caps.armor*100,'%')}${row('正常回盾 / 秒',p.regen,caps.regen)}</div><div class="hero-stage"><div class="hero-stage-title">${RealmVisuals.get(c).motif}</div><canvas id="heroPreview" width="340" height="430" aria-label="${HeroIdentity.get(heroId).name}当前境界动态展示"></canvas><div class="hero-realm">${Cultivation.label(c)}</div></div><div class="hero-offense">${row('伤害倍率',p.dmg,caps.dmg,'×')}${row('暴击',p.crit*100,caps.crit*100,'%')}${row('冷却缩减',(1-p.cdr)*100,(1-caps.cdr)*100,'%')}${row('移速',p.speed,caps.speed)}${row('拾取范围',p.pickup,caps.pickup)}${row('经验倍率',p.xpMul,caps.xpMul,'×')}</div></div><div class="cultivation-meter"><i style="width:${Math.min(100,c.qi/Cultivation.need(c)*100)}%"></i><span>本境修为 ${n(c.qi)} / ${n(Cultivation.need(c))} · ${c.layer}/9层</span></div><h3>已习术法</h3><div class="inventory-grid">${spells}</div><h3>携行法宝</h3><div class="inventory-grid">${equips}</div><h3>天材地宝</h3><div class="material-grid">${materials}</div><footer class="sheet-note">C / Esc 关闭 · 返回选人页后可继续历程或重新出征</footer></div>`;
    document.getElementById('closeCharacterBtn').onclick=close;document.getElementById('closeCharacterBtn').focus?.();return true;
  }
  function draw(){
    if(G.state!=='character')return;
    const c=P.cultivation,r=Cultivation.recipe(),caps=Cultivation.caps(),ov=document.getElementById('overlay');
    ov.classList.remove('hidden','journey-screen','title-screen');
    const row=(name,current,limit,suffix='')=>`<div class="attribute-row"><span>${name}</span><b>${n(current)}${suffix}</b><small>上限 ${n(limit)}${suffix}</small></div>`;
    const stats=row('生命',P.hp,P.maxHp)+row('生命上限',P.maxHp,caps.maxHp)+row('护盾',P.shield,P.shieldMax)+row('护盾上限',P.shieldMax,caps.shieldMax)+row('伤害倍率',P.dmg,caps.dmg,'×')+row('暴击率',P.crit*100,caps.crit*100,'%')+row('受到伤害减免',P.armor*100,caps.armor*100,'%')+row('冷却缩减 · 含大招',(1-P.cdr)*100,(1-caps.cdr)*100,'%')+row('移速',P.speed,caps.speed)+row('拾取范围',P.pickup,caps.pickup)+row('护盾回复 / 秒',P.regen,caps.regen)+row('经验倍率',P.xpMul,caps.xpMul,'×');
    const spells=Object.entries(P.spells).map(([id,level])=>`<div class="inventory-item"><b>${SPELLS[id].name} · Lv.${level}</b><small>${SpellGrowth.describe(id,level)} · 上限 Lv.${Math.max(level,SpellGrowth.cap())}</small></div>`).join('');
    const equips=P.equips.map(id=>{const e=EQUIPS.find(e=>e.id===id);return `<div class="inventory-item"><b>${ItemCatalog.icon(e.id,e.name)}${e.name}</b><small>${e.desc}</small></div>`;}).join('')||'<p>暂无法宝</p>';
    const materials=[['essence','灵蕴精华'],...Cultivation.cores.map((name,i)=>['core'+(i+1),name])].map(([id,name])=>`<div class="material-item">${ItemCatalog.icon(id,name)}<span>${name}<small>${ItemCatalog.meta(id).use}</small></span><b>${c.materials[id]||0}</b></div>`).join('');
    let body=tab==='stats'?`<div class="character-constellation"><div class="hero-survival">${row('生命',P.hp,P.maxHp)}${row('生命最大值',P.maxHp,caps.maxHp)}${row('护盾',P.shield,P.shieldMax)}${row('护盾最大值',P.shieldMax,caps.shieldMax)}${row('减伤',P.armor*100,caps.armor*100,'%')}${row('正常回盾 / 秒',P.regen,caps.regen)}${row('交战回盾 / 秒',P.regen*.25,caps.regen*.25)}<p class="sheet-note">${CombatScaling.regenState().wait>0?'受伤后等待 '+CombatScaling.regenState().wait.toFixed(1)+' 秒恢复':CombatScaling.regenState().engaged?'交战回盾 · 正常速率的25%':'正常回盾'} · ${CombatScaling.hud()}</p></div><div class="hero-stage"><div class="hero-stage-title">${RealmVisuals.get(c).motif}</div><canvas id="heroPreview" width="340" height="430" aria-label="${HeroIdentity.get(P.heroId).name}当前境界动态展示"></canvas><div class="hero-realm">${Cultivation.label()}</div><div class="hero-equipment-slots">${Array.from({length:8},(_,i)=>{const equip=EQUIPS.find(e=>e.id===P.equips[i]);return `<span title="${equip?equip.name+'：'+equip.desc:'法宝空位'}">${equip?ItemCatalog.icon(equip.id,equip.name):'◇'}<small>${equip?equip.name:'法宝'}</small></span>`;}).join('')}</div></div><div class="hero-offense">${row('伤害倍率',P.dmg,caps.dmg,'×')}${row('暴击',P.crit*100,caps.crit*100,'%')}${row('冷却缩减 · 含大招',(1-P.cdr)*100,(1-caps.cdr)*100,'%')}${row('移速',P.speed,caps.speed)}${row('拾取范围',P.pickup,caps.pickup)}${row('经验倍率',P.xpMul,caps.xpMul,'×')}</div></div><p class="sheet-note">属性显示当前值 / 当前最大值或境界上限 · 每层灵纹增强 · 每境独立法相</p><p class="sheet-note">${Cultivation.autoStatus()}</p><h3>已习术法</h3><div class="inventory-grid">${spells}</div><h3>携行大招 · 独立剑意 / 冷却</h3><div class="inventory-grid">${UltimateArts.sheet()}</div><h3>携行法宝</h3><div class="inventory-grid">${equips}</div>`:tab==='bag'?`<h3>天材地宝</h3><p class="sheet-note">对应关卡大妖30%概率掉落本境破境宝物；对应境界三关全部通关后开放域外超级大妖，生命与伤害均为2倍，胜利100%获得核心材料和灵蕴各50%配方。普通妖怪与精英可补充灵蕴。本轮已领稀有奖励不会因刷新或死亡重发。</p><div class="material-grid">${materials}</div>`:'';
    if(tab==='spells'){
      if(!giftDraft)giftDraft={...SpellGift.ensure().levels};
      const current=SpellGift.effective(),draft=SpellGift.effective(giftDraft),safe=SpellGift.safe()&&!RunSave.conflicted();
      body=`<div class="gift-heading"><div><span class="overline">大境界突破赠礼 · 可暂存</span><h3>术法赠礼：剩余 ${SpellGift.remaining(giftDraft)} 点</h3><p>每次破境获得3点术法赠礼 · 共获得 ${3*c.realm} 点</p></div><button id="resetGiftBtn">撤回赠送升级 · 预览</button></div><p class="sheet-note">本境术法上限 Lv.${SpellGrowth.cap()}；每次突破上限 +3级${c.realm<13?'，下一境开放至 Lv.'+SpellGrowth.cap(c.realm+1):''}。飞剑、万剑与五雷加强数量，其余术法扩大作用距离或范围。万剑每五级展开新圈，每级增加剑数。未习得术法也可投入赠礼：1点习得Lv.1，习得后每升一级再消耗1点，赠礼可以补学至全部八门；普通升级与宝箱成长永久保留。安全时免费调整，确认前不影响战斗。新加入术法从完整冷却开始。</p><div class="gift-grid">${SpellGift.keys.map(key=>{const old=current[key]||0,l=draft[key]||0,base=SpellGift.base()[key]||0;return `<article class="gift-card" style="--spell:${SPELLS[key].color}"><header><b>${SPELLS[key].glyph} ${SPELLS[key].name}</b><strong>${old?(old===l?'已习得 · Lv.'+old:'Lv.'+old+' → '+(l?'Lv.'+l:'未习得')):l?'待习得 · Lv.'+l:'未习得'}</strong></header><small>${SpellGrowth.focus(key)} · 永久 ${base}级 · 赠送 ${giftDraft[key]||0}级 · 上限 ${Math.max(base,SpellGrowth.cap())}级</small>${RewardCards.spellHTML(key,old,l)}<p class="gift-change">${SpellGrowth.change(key,old,l)}</p><div class="gift-controls"><button data-gift-minus="${key}" aria-label="撤回${SPELLS[key].name}一级" ${!giftDraft[key]?'disabled':''}>−</button><span>投入 ${giftDraft[key]||0} 点</span><button data-gift-plus="${key}" class="${!l?'gift-learn':''}" aria-label="${!l?'习得':'升级'}${SPELLS[key].name}${!l?'，消耗1点':'一级，消耗1点'}" title="${SpellGift.remaining(giftDraft)<=0?'赠礼点不足':!SpellGift.canAdd(giftDraft,key)?'已达本境上限':!l?'消耗1点习得Lv.1，确认后生效':'消耗1点提升一级，确认后生效'}" ${!SpellGift.canAdd(giftDraft,key)?'disabled':''}>${!l?'习得 · 1点':'＋'}</button></div></article>`;}).join('')}</div><p id="giftError" role="status">${giftError||(!safe?'脱离首领战且附近650范围内无交战妖怪后，才可确认调整。':'当前安全，可以确认调整。')}</p><button class="btn" id="applyGiftBtn" ${!safe?'disabled':''}>确认本次术法调整</button>`;
    }
    if(tab==='break'){
      const outcome=c.result;
      const history=outcome?.success?`<p class="sheet-note">上次破境：${Cultivation.realms[outcome.target]} · 第${outcome.attempt}次 · 已保存</p>`:'';
      body=r?`<div class="break-heading"><span>${Cultivation.label()} →</span><h3>${Cultivation.realms[r.target]}</h3></div><p class="sheet-note">九层圆满、修为和完整材料达标后自动破境。大境界提升会暂停当前内容，播放专属演出，再返回原来的战斗或界面。暂停与离开网页期间保留进度。</p><div class="break-recipe"><label>本境修为<small>${n(c.qi)} / ${n(r.qi)}</small></label><label>${r.name}<small>${c.materials[r.core]||0} / ${r.coreCount}</small></label><label>灵蕴精华<small>${c.materials.essence||0} / ${r.essence}</small></label></div><div class="break-preview"><strong>${Cultivation.autoStatus()}</strong><span>破境后：生命与护盾上限基础 +12% · 伤害 +8% · 术法赠礼 +3</span><span>${RealmVisuals.ascensions[r.target]} · 专属天地法相</span></div><p class="sheet-note">${r.name}：本境对应关卡大妖30%掉落；本境三关全部通关后开放域外超级大妖，每战保底获得核心与灵蕴配方各50%。</p>${history}`:`<div class="break-result success"><h3>${Cultivation.label()}</h3><p>已达修炼终境；继续在游戏中积累修为，自动修至仙王九层道圆。</p>${history}</div>`;
    }
    ov.innerHTML=`<div class="panel character-panel"><header class="character-header"><div><span class="overline">无籍剑仙 · ${HeroIdentity.get(P.heroId).name}</span><h2>${Cultivation.label()}</h2><p>战斗等级 Lv.${P.level} · 经验 ${n(P.xp)} / ${n(P.xpNext)} · 剑意 ${n(P.energy)}%</p></div><button id="closeCharacterBtn" aria-label="关闭人物面板">×</button></header><div class="cultivation-meter"><i style="width:${Math.min(100,c.qi/Cultivation.need(c)*100)}%"></i><span>${'本境修为 '+n(c.qi)+' / '+n(Cultivation.need(c))+' · '+(c.qi>=Cultivation.need(c)?'九层圆满':c.layer+' / 9层')}</span></div><nav class="character-tabs">${[['stats','人物状态'],['spells','术法赠礼 · '+SpellGift.remaining()],['bag','天材地宝'],['break','境界突破']].map(([id,name])=>`<button data-sheet="${id}" aria-pressed="${id===tab}">${name}</button>`).join('')}</nav><section class="character-content">${body}</section><footer class="sheet-note">${RunSave.status()} · C / Esc 关闭 · 面板开启时战斗暂停</footer></div>`;
    document.getElementById('closeCharacterBtn').onclick=close;
    ov.querySelectorAll('[data-sheet]').forEach(button=>button.onclick=()=>{tab=button.dataset.sheet;draw();});
    if(tab==='spells'){
      ov.querySelectorAll('[data-gift-plus]').forEach(b=>b.onclick=()=>{const key=b.dataset.giftPlus;if(SpellGift.canAdd(giftDraft,key))giftDraft[key]=(giftDraft[key]||0)+1;giftError='';draw();});
      ov.querySelectorAll('[data-gift-minus]').forEach(b=>b.onclick=()=>{const key=b.dataset.giftMinus;if(giftDraft[key])giftDraft[key]--;if(!giftDraft[key])delete giftDraft[key];giftError='';draw();});
      document.getElementById('resetGiftBtn').onclick=()=>{giftDraft={};giftError='当前仅预览撤回，确认后生效。';draw();};
      document.getElementById('applyGiftBtn').onclick=()=>{const learned=Object.keys(SpellGift.effective(giftDraft)).filter(key=>!P.spells[key]);giftError=SpellGift.apply(giftDraft)?learned.length?'已习得：'+learned.map(key=>SPELLS[key].name+' Lv.'+P.spells[key]).join('、')+' · 赠礼点已结算并保存。':'术法调整已保存。':'调整未执行：'+RunSave.status();draw();};
    }
  }

  function coreRewardHTML(){if(!G.coreReward)return '';const target=G.coreReward.max;return `<div class="core-reward"><h3>守关天材地宝 · 定向领取</h3><div class="core-portrait" id="corePortrait">${ItemCatalog.icon('core'+target,Cultivation.cores[target-1])}</div><div id="corePreview">${RewardCards.coreHTML(target,G.coreReward.count||1)}</div><p>${Cultivation.realms[ChapterCatalog.get(Journey.run.stage).realm]}篇守关奖励 · 领取后才可继续前行</p><select id="bossCoreSelect" aria-label="选择首领核心材料">${Cultivation.cores.slice(0,target).map((name,i)=>`<option value="${i+1}" ${i+1===target?'selected':''}>${name} ×${G.coreReward.count||1} · 用于突破${Cultivation.realms[i+1]}</option>`).join('')}</select><button class="btn" id="claimBossCoreBtn">收下所选天材地宝</button></div>`;}
  function bindCoreReward(){if(G.coreReward){const select=document.getElementById('bossCoreSelect');select.onchange=()=>{document.getElementById('corePreview').innerHTML=RewardCards.coreHTML(Number(select.value),G.coreReward.count||1);document.getElementById('corePortrait').innerHTML=ItemCatalog.icon('core'+select.value,Cultivation.cores[Number(select.value)-1]);};document.getElementById('claimBossCoreBtn').onclick=()=>Cultivation.claimCore(Number(select.value));}}
  function decorateMenu(){
    const ov=document.getElementById('overlay'),s=RunSave.summary();
    if(s){const slot=document.createElement('section');slot.className='continue-card';slot.innerHTML=`<div><span class="overline">自动保存的寻圣历程</span><strong>第${s.stage+1}难 · ${s.realm} · Lv.${s.level}</strong><small>${s.savedAt?new Date(s.savedAt).toLocaleString('zh-CN'):'旧版入口存档 · 将安全迁移'}</small></div><button class="btn" id="continueRunBtn">继续历程 →</button>`;ov.querySelector('.journey-menu').prepend(slot);document.getElementById('continueRunBtn').onclick=()=>RunSave.continueRun(Journey.run.heroId);const saved=RunSave.snapshot();}

    if(s){const start=document.getElementById('startBtn'),saved=RunSave.snapshot();const pending=saved&&(saved.run.queue>0||saved.run.chestReward||saved.run.pendingLore!==null&&saved.run.pendingLore!==undefined||saved.run.coreReward);start.textContent=pending?'请先继续历程 · 处理待领奖励':'以当前人物重战所选章节 →';start.disabled=!!pending;}
  }
  function frame(time){if(G.state!=='character-preview'&&(G.state!=='character'||!['stats','break'].includes(tab)))return;const p=G.state==='character-preview'?menuPlayer:P,canvas=document.getElementById('heroPreview');if(canvas?.getContext)Motion.preview(canvas.getContext('2d'),time,p.cultivation,p.heroId);}
  return {init,toggle,close,draw,frame,openFromMenu,coreRewardHTML,bindCoreReward,decorateMenu};
})();
